create role anon;create role authenticated;create role service_role;
 create schema auth;create table auth.users(id uuid primary key);
 create table public.icash_accounts(id uuid primary key,owner_user_id uuid);
 create table public.icash_operating_budget(id int primary key);insert into public.icash_operating_budget values(1);
 create table public.icash_screening_jobs(id uuid primary key,account_id uuid,snapshot jsonb);
 create table public.icash_deal_files(id uuid primary key,account_id uuid,screening_id uuid,terms jsonb default '{}',stage text default 'draft' check(stage in ('draft','under_contract','buyer_selected','title_open','closing','closed')),seller_signed_at timestamptz,assignment_signed_at timestamptz,title_verified_at timestamptz,funded_at timestamptz,updated_at timestamptz default now());
 create table public.icash_signing_envelopes(id uuid primary key,account_id uuid,deal_id uuid,kind text,test_mode boolean default false,state text check(state in ('creating','awaiting_counterparty','customer_signature_needed','completed','test_completed','needs_review')),provider_id text unique,provider_status text,provider_evidence jsonb,terms jsonb default '{}',updated_at timestamptz default now(),unique(deal_id,kind,test_mode));
 create table public.icash_signature_authorizations(envelope_id uuid,account_id uuid,state text);
 create table public.icash_property_controls(account_id uuid,property_id text,manual boolean,updated_at timestamptz,primary key(account_id,property_id));
 create table public.icash_buyer_deposit_receipts(id uuid primary key default gen_random_uuid(),account_id uuid,deal_id uuid unique,envelope_id uuid,amount_cents bigint);
 create table public.icash_title_requests(id uuid primary key default gen_random_uuid(),account_id uuid,deal_id uuid,state text);
 create table public.icash_closing_updates(id uuid default gen_random_uuid(),account_id uuid,deal_id uuid,kind text,amount_cents bigint,confirmed_by uuid);
 create table public.icash_closing_setup(account_id uuid,deal_id uuid,state text,review_reason text,updated_at timestamptz);
 create table public.icash_text_threads(id uuid primary key,account_id uuid,deal_id uuid,party text,paused boolean default false);
 create table public.icash_text_messages(id uuid primary key default gen_random_uuid(),thread_id uuid,account_id uuid,direction text,state text);
 create table public.icash_fulfillment_jobs(id uuid primary key default gen_random_uuid(),account_id uuid,deal_id uuid,state text,updated_at timestamptz);
 create table public.icash_live_callbacks(account_id uuid,screening_id uuid,state text);
 create table public.icash_buyer_package_links(account_id uuid,deal_id uuid,revoked_at timestamptz);
 create table public.icash_title_replies(id uuid primary key,account_id uuid,deal_id uuid,received_at timestamptz);
 create function public.icash_save_signing_status(p_id uuid,p_state text,p_evidence jsonb) returns void language plpgsql as $$begin update public.icash_signing_envelopes set state=p_state,provider_evidence=p_evidence where id=p_id;end$$;
 create function public.icash_buyer_is_reserved(p_account uuid,p_deal uuid) returns boolean language sql as $$select exists(select 1 from public.icash_buyer_deposit_receipts where account_id=p_account and deal_id=p_deal)$$;
 create function public.icash_buyer_outreach_held(uuid,uuid) returns boolean language sql as $$select false$$;
 create function public.icash_set_work_control(p_user uuid,p_account uuid,p_action text,p_screening uuid default null) returns void language plpgsql as $$begin update public.icash_property_controls set manual=false where account_id=p_account and property_id=p_screening::text;end$$;
 create function public.icash_confirm_closing_update(p_account uuid,p_actor uuid,p_deal uuid,p_reply uuid,p_kind text,p_date date default null,p_amount bigint default null,p_file text default '') returns uuid language sql as $$select gen_random_uuid()$$;
 
alter table public.icash_accounts add column bot_paused boolean default false;
alter table public.icash_screening_jobs add column state text default 'complete';
alter table public.icash_signing_envelopes add column recipients jsonb default '[]';
alter table public.icash_text_threads alter column id set default gen_random_uuid();
alter table public.icash_text_threads add column recipient text,add column sender text,add column retired_at timestamptz,add column sms_rate_id uuid,add column seller_intake_id uuid,add column manual_only boolean default false,add column ai_mode text default 'auto',add column dnc_clear boolean default false,add column dnc_checked_at timestamptz,add column sms_review_request_id uuid,add column operational_contact_id uuid,add column permission_evidence text,add column permission_until timestamptz,add column timezone text default 'UTC',add column seller_sms_rate_hash text,add column seller_sms_price_micros bigint;
alter table public.icash_text_messages add column body text,add column request_key uuid unique,add column asset_ids uuid[] default '{}',add column attachments jsonb default '[]',add column customer_author_id uuid,add column created_at timestamptz default now(),add column updated_at timestamptz default now();
alter table public.icash_operating_budget add column standard_cost_multiplier numeric default 3,add column elevenlabs_cost_multiplier numeric default 3;
create table public.icash_customer_identities(account_id uuid,principal text);
create table public.icash_title_contacts(account_id uuid,deal_id uuid,email text,enabled boolean,verified_until timestamptz);
create table public.icash_seller_intakes(id uuid,phone text,email text,email_consented boolean,data_rights_until timestamptz,created_at timestamptz default now());
create table public.icash_seller_matches(account_id uuid,screening_id uuid,lead_id uuid);
create table public.icash_email_suppressions(account_id uuid,email text);
create table public.icash_text_suppressions(phone text);
create table public.icash_contact_suppressions(contact_key text);
create table public.icash_text_senders(phone text,enabled boolean);
create table public.icash_communication_prices(operation text,customer_micros bigint);
create table public.icash_handoffs(account_id uuid,screening_id uuid,state text);
create table public.icash_operation_rates(id uuid primary key,operation text,enabled boolean,verified_at timestamptz,expires_at timestamptz,voice_max_duration_seconds integer,charge_cents bigint,version text,costs_micros jsonb,buffer_bps int default 0);
create table public.icash_voice_contact_targets(id uuid primary key,account_id uuid,screening_id uuid,party text,phone text,contact_key text,revoked_at timestamptz,permission_until timestamptz,dnc_clear boolean,dnc_checked_at timestamptz,timezone text,local_start_hour int default 0,local_end_hour int default 24);
create table public.icash_contact_permissions(id uuid primary key,account_id uuid);
create table public.icash_voice_configs(account_id uuid,enabled boolean,reviewed_until timestamptz,seller_rate_id uuid);
create table public.icash_voice_jobs(id uuid primary key default gen_random_uuid(),account_id uuid,permission_id uuid,operational_contact_id uuid,callback_id uuid,sms_source_message_id uuid,state text default 'ready',due_at timestamptz default now(),outcome text,provider_call_sid text,conversation_id text,operation_key text,updated_at timestamptz default now());
create unique index icash_voice_first_once on public.icash_voice_jobs(permission_id) where callback_id is null and sms_source_message_id is null;
create unique index icash_voice_operational_first_once on public.icash_voice_jobs(operational_contact_id) where callback_id is null;
create table public.icash_deal_emails(id uuid primary key default gen_random_uuid(),account_id uuid,deal_id uuid,direction text,contact_key text,recipient text,subject text,body_text text,state text,request_key uuid,rate_id uuid,permission_until timestamptz,authored_by uuid,delivery_state text,updated_at timestamptz default now());
create table public.icash_operation_spend(operation_key text primary key,account_id uuid,rate_id uuid,state text,financial_checked_at timestamptz);
create table public.icash_voice_credit_bounds(operation_key text primary key,account_id uuid,rate_id uuid,max_seconds int,charge_cents bigint,costs_micros jsonb);
create table public.icash_live_conversations(account_id uuid,contact_key text,state text);
create table public.icash_call_recordings(id uuid default gen_random_uuid(),voice_job_id uuid,call_sid text,call_ended_at timestamptz);
-- Provider/billing boundaries are isolated fixtures. The new queue/admission functions below are the actual migration.
create function public.icash_manual_text_reason(uuid,uuid) returns text language sql as $$select case when exists(select 1 from public.icash_text_threads t join public.icash_text_suppressions s on s.phone=t.recipient where t.account_id=$1 and t.id=$2) then 'Contact stopped texts' end$$;
create function public.icash_queue_text(uuid,uuid,uuid,text,uuid[]) returns uuid language plpgsql as $$declare n uuid;begin if length($4)>160 then raise exception 'Shorten message';end if;insert into public.icash_text_messages(account_id,thread_id,request_key,body,asset_ids,state,direction) values($1,$2,$3,$4,$5,'ready','outgoing') returning id into n;return n;end$$;
create function public.icash_claim_customer_text(p_account uuid,p_message uuid,p_sender text) returns jsonb language plpgsql as $$declare m public.icash_text_messages;begin select * into m from public.icash_text_messages where id=p_message and account_id=p_account and state='ready' for update;if not found then return null;end if;update public.icash_text_messages set state='dispatching' where id=m.id;return jsonb_build_object('message',m.body);end$$;
create function public.icash_claim_text(uuid,uuid,text) returns jsonb language sql as $$select null::jsonb$$;
create function public.icash_claim_deal_email(uuid,uuid) returns jsonb language sql as $$select null::jsonb$$;
create function public.icash_seller_voice_permission_current(uuid,uuid) returns boolean language sql as $$select true$$;
create function public.icash_operational_contact_current(uuid,uuid,text,boolean) returns boolean language sql as $$select true$$;
create function public.icash_limited_seller_voice(uuid,text) returns boolean language sql as $$select false$$;
create function public.icash_vip_active(uuid) returns boolean language sql as $$select false$$;
create function public.icash_voice_bounded_costs(jsonb,integer) returns jsonb language sql as $$select $1$$;
create function public.icash_reserve_before_fractional(p_account uuid,p_operation text,p_rate uuid,p_permission_until timestamptz,p_financial_checked_at timestamptz default null,p_financial_eligible boolean default false) returns jsonb language plpgsql as $$declare r public.icash_operation_rates;begin select * into r from public.icash_operation_rates where id=p_rate;if r.operation='seller_call' and not public.icash_limited_seller_voice(p_account,p_operation) and not p_financial_eligible then raise exception 'Financial screening required';end if;insert into public.icash_operation_spend values(p_operation,p_account,p_rate,'reserved',p_financial_checked_at) on conflict do nothing;return '{}'::jsonb;end$$;
create function public.icash_claim_before_activation(p_operation text) returns boolean language plpgsql as $$declare r public.icash_operation_rates;o public.icash_operation_spend;begin select * into o from public.icash_operation_spend where operation_key=p_operation and state='reserved';if not found then return false;end if;select * into r from public.icash_operation_rates where id=o.rate_id;if r.operation='seller_call' and not public.icash_limited_seller_voice(o.account_id,p_operation) and o.financial_checked_at is null then return false;end if;update public.icash_operation_spend set state='dispatched' where operation_key=p_operation;return true;end$$;
create function public.icash_reserve_operation(uuid,text,uuid,timestamptz,timestamptz default null,boolean default false) returns jsonb language sql as $$select public.icash_reserve_before_fractional($1,$2,$3,$4,$5,$6)$$;
create function public.icash_claim_operation(text) returns boolean language sql as $$select public.icash_claim_before_activation($1)$$;
create function public.icash_sms_intake_rate_current(uuid) returns boolean language sql as $$select true$$;
create function public.icash_outreach_sms_current(uuid) returns boolean language sql as $$select true$$;
create function public.icash_seller_sms_inquiry_window(uuid,uuid) returns boolean language sql as $$select true$$;
create function public.icash_seller_contact_evidence(uuid,uuid,uuid,text) returns jsonb language sql as $$select null::jsonb$$;
create function public.icash_sms_thread_review_current(uuid,uuid,boolean default true) returns boolean language sql as $$select false$$;
